{
  "schema_version": 4,
  "name": "Create & manage incident comms via Slack",
  "description": "This Story allows teams to create and manage incident communication directly through Slack. It can create Slack channels for communications, and sync conversation backups to a Jira ticket for long-term preservation.\n\ntags: Slack, Jira, Chatbots, CaseManagement, Advanced,\nicons: slack,🧑‍🚒, 💾\nvisibility: public",
  "guid": "9b5a1b4b1cda4a94704221d479fa0a08",
  "slug": "create_manage_incident_comms_via_slack",
  "exported_at": "2022-07-11T17:45:17Z",
  "agents": [
    {
      "type": "Agents::WebhookAgent",
      "name": "Receive Commands",
      "disabled": false,
      "guid": "6aed622ce3ee4b9c86c4967d188c578c",
      "options": {
        "secret": "REDIGIDO-PELO-DETECTIONRULES",
        "verbs": "get,post",
        "response": "",
        "response_code": "200",
        "path": "12446c94949ec17daea98840dee253d9"
      },
      "reporting": {
        "time_saved_value": 0,
        "time_saved_unit": "minutes"
      },
      "monitoring": {
        "monitor_all_events": false,
        "monitor_failures": false,
        "monitor_no_events_emitted": null
      }
    },
    {
      "type": "Agents::HTTPRequestAgent",
      "name": "Create Incident Channel in Slack",
      "disabled": false,
      "guid": "5376305dc422591924129487b9dd79b6",
      "options": {
        "url": "https://slack.com/api/conversations.create",
        "content_type": "json",
        "method": "post",
        "payload": {
          "name": "incident_channel_<<DEFAULT(create_issue_in_jira.body.key, parse_response.view.state.values.jira_textbox_block.jira_id.value) |> REPLACE(%, \"-\", \"_\") |> DOWNCASE(%)>>",
          "is_private": true
        },
        "headers": {
          "Authorization": "Bearer <<CREDENTIAL.slack>>"
        }
      },
      "reporting": {
        "time_saved_value": 0,
        "time_saved_unit": "minutes"
      },
      "monitoring": {
        "monitor_all_events": false,
        "monitor_failures": false,
        "monitor_no_events_emitted": null
      },
      "schedule": null
    },
    {
      "type": "Agents::HTTPRequestAgent",
      "name": "Add Users to Incident Channel in Slack",
      "disabled": false,
      "guid": "71b5f247b0200a9d26283899805d2973",
      "options": {
        "url": "https://slack.com/api/conversations.invite",
        "content_type": "json",
        "method": "post",
        "payload": {
          "channel": "<<create_incident_channel_in_slack.body.channel.id>>",
          "users": "<<JOIN(parse_response.view.state.values.incident_channel_users[\"users_select-action\"].selected_users, \",\")>>"
        },
        "headers": {
          "Authorization": "Bearer <<CREDENTIAL.slack>>"
        }
      },
      "reporting": {
        "time_saved_value": 0,
        "time_saved_unit": "minutes"
      },
      "monitoring": {
        "monitor_all_events": false,
        "monitor_failures": false,
        "monitor_no_events_emitted": null
      },
      "schedule": null
    },
    {
      "type": "Agents::HTTPRequestAgent",
      "name": "Create Modal",
      "disabled": false,
      "guid": "6f3b5ae78b40590273e76edc5701f9c6",
      "options": {
        "url": "https://slack.com/api/views.open",
        "content_type": "json",
        "method": "post",
        "headers": {
          "Authorization": "Bearer <<CREDENTIAL.slack>>"
        },
        "payload": {
          "trigger_id": "<<receive_commands.body.trigger_id>>",
          "view": {
            "type": "modal",
            "callback_id": "create_channel",
            "notify_on_close": true,
            "title": {
              "type": "plain_text",
              "text": "Create Incident Channel",
              "emoji": true
            },
            "submit": {
              "type": "plain_text",
              "text": "Submit",
              "emoji": true
            },
            "close": {
              "type": "plain_text",
              "text": "Cancel",
              "emoji": true
            },
            "blocks": [
              {
                "type": "section",
                "text": {
                  "type": "mrkdwn",
                  "text": "Complete this form to create Incident Slack Channels"
                }
              },
              {
                "type": "divider"
              },
              {
                "type": "input",
                "element": {
                  "type": "plain_text_input",
                  "action_id": "jira_id"
                },
                "label": {
                  "type": "plain_text",
                  "text": "Enter Incident ID (if available)",
                  "emoji": true
                },
                "block_id": "jira_textbox_block",
                "optional": "true"
              },
              {
                "type": "input",
                "element": {
                  "type": "radio_buttons",
                  "initial_option": {
                    "text": {
                      "type": "mrkdwn",
                      "text": "*Use Existing Incident included above*"
                    },
                    "value": "existing"
                  },
                  "options": [
                    {
                      "text": {
                        "type": "mrkdwn",
                        "text": "*Use Existing Incident included above*"
                      },
                      "value": "existing"
                    },
                    {
                      "text": {
                        "type": "mrkdwn",
                        "text": "*Create New Incident*"
                      },
                      "value": "new"
                    }
                  ],
                  "action_id": "new_incident-action"
                },
                "label": {
                  "type": "plain_text",
                  "text": "Optional: Create new Incident"
                },
                "block_id": "new_incident_block"
              },
              {
                "type": "divider"
              },
              {
                "type": "section",
                "text": {
                  "type": "mrkdwn",
                  "text": "Select Users to add to Incident Channel"
                },
                "accessory": {
                  "type": "multi_users_select",
                  "placeholder": {
                    "type": "plain_text",
                    "text": "Select a user",
                    "emoji": true
                  },
                  "action_id": "users_select-action"
                },
                "block_id": "incident_channel_users"
              },
              {
                "type": "divider"
              },
              {
                "type": "section",
                "text": {
                  "type": "mrkdwn",
                  "text": "If an Executive Comms Channel is required for this incident, add users here. This is optional."
                },
                "accessory": {
                  "type": "multi_users_select",
                  "placeholder": {
                    "type": "plain_text",
                    "text": "Select a user",
                    "emoji": true
                  },
                  "action_id": "users_select-action"
                },
                "block_id": "exec_channel_users"
              }
            ]
          }
        }
      },
      "reporting": {
        "time_saved_value": 0,
        "time_saved_unit": "minutes"
      },
      "monitoring": {
        "monitor_all_events": false,
        "monitor_failures": false,
        "monitor_no_events_emitted": null
      },
      "schedule": []
    },
    {
      "type": "Agents::TriggerAgent",
      "name": "Modal Response",
      "disabled": false,
      "guid": "d4229a64485c34ed6944f6e69b9cae84",
      "options": {
        "rules": [
          {
            "type": "regex",
            "value": "view_submission",
            "path": "<<receive_commands.body.payload>>"
          }
        ]
      },
      "reporting": {
        "time_saved_value": 0,
        "time_saved_unit": "minutes"
      },
      "monitoring": {
        "monitor_all_events": false,
        "monitor_failures": false,
        "monitor_no_events_emitted": null
      }
    },
    {
      "type": "Agents::TriggerAgent",
      "name": "Incident Slack Command Found",
      "disabled": false,
      "guid": "0074c96c335404150659c293e76c6cba",
      "options": {
        "rules": [
          {
            "type": "field==value",
            "value": "/incident",
            "path": "<<receive_commands.body.command>>"
          },
          {
            "type": "field==value",
            "value": "create",
            "path": "<<receive_commands.body.text>>"
          }
        ],
        "must_match": "1"
