  "exported_at": "2022-07-11T17:29:02Z",
  "agents": [
    {
      "type": "Agents::WebhookAgent",
      "name": "Receive Command",
      "disabled": false,
      "guid": "7fb23f9c2ed21a4e1e586ab12c19d131",
      "options": {
        "secret": "REDIGIDO-PELO-DETECTIONRULES",
