        "url": "https://<<RESOURCE.splunk_domain>>:8089/services/search/jobs/<<search_splunk.body.sid>>?output_mode=json",
        "content_type": "json",
        "method": "get",
        "disable_ssl_verification": "true",
        "headers": {
          "Authorization": "Basic <<CREDENTIAL.splunk>>"
        }
      },
      "reporting": {
        "time_saved_value": 0,
        "time_saved_unit": "minutes"
