        "payload": {
          "search": "search source=proxy host=webproxy sourcetype=Bluecoat s_ip=* <<receive_form.body.domain>> | table s_ip _time c_ip cs_host cs_method cs_uri_path sc_status cs_Referer cs_User_Agent _raw"
