{
  "schema_version": 4,
  "name": "Retrieve & enrich Okta alerts from Logz.io",
  "description": "Retrieve Okta alerts from Logz.io and enrich the information with extra IP reputation context. Users can be contacted via Slack to confirm or deny this activity to help in auto-closing or escalating these alerts.\n\ntags: Logz.io, Okta, Slack, SIEM, Intermediate\nicons: logz, 🔔, slack\nvisibility: public",
  "guid": "f879d6da05f9b3fa400141f79b8a1d1b",
